// ATOM2_W07 · Devidas agora (trecho de n8n/code/w07_cadencia.js).
const FERIADOS = ['2026-01-01', '2026-02-16', '2026-02-17', '2026-04-03', '2026-04-21', '2026-05-01', '2026-06-04', '2026-09-07', '2026-10-12', '2026-11-02', '2026-11-15', '2026-11-20', '2026-12-25',
  '2027-01-01', '2027-02-08', '2027-02-09', '2027-03-26', '2027-04-21', '2027-05-01', '2027-05-27', '2027-09-07', '2027-10-12', '2027-11-02', '2027-11-15', '2027-11-20', '2027-12-25'];
const SEQ = { OUT: { D1: ['D3', 2], D3: ['D6', 3], D6: ['D9', 3], D9: ['D12', 3], D12: [null, 0] }, POS: { D9: ['D12', 3], D12: [null, 0] }, PROP: { P2: ['P5', 3], P5: [null, 0] } };
// Até 10 mensagens por rodada de 15 min (espaça os envios e protege a reputação do número).
const LIMITE_POR_EXECUCAO = 10;
// --- tempo em São Paulo (UTC−3 fixo; o Brasil não tem horário de verão desde 2019) ---
const SP = (d) => new Date(new Date(d).getTime() - 3 * 3600 * 1000);
const diaSP = (d) => SP(d).toISOString().slice(0, 10);
const util = (dia) => { const w = new Date(dia + 'T12:00:00Z').getUTCDay(); return w !== 0 && w !== 6 && !FERIADOS.includes(dia); };
function horarioComercial(agora) { const s = SP(agora); const h = s.getUTCHours(); return util(s.toISOString().slice(0, 10)) && h >= 8 && h < 18; }
// Cadências devidas agora, sem as que já têm a mensagem do passo registrada (em SIMULACAO a cadência não avança:
// sem esse filtro as mesmas 10 ocupariam todas as rodadas e as demais nunca seriam processadas).
// manual = execução manual: fora do horário comercial processa só registros de teste (c_teste_*).
function devidas(cadencias, agoraISO, manual, mensagens) {
  const agora = agoraISO || new Date().toISOString();
  const fora = !horarioComercial(agora);
  if (fora && !manual) return [];
  const ja = new Set((mensagens || []).filter((m) => m && m.msg_id).map((m) => m.msg_id));
  return (cadencias || []).filter((x) => x && (!fora || String(x.company_id).startsWith('c_teste_')) && x.status === 'ativa' && x.proximo_passo && String(x.proximo_em) <= agora && !ja.has(msgIdDe(x)))
    .sort((a, b) => String(a.proximo_em).localeCompare(String(b.proximo_em))).slice(0, LIMITE_POR_EXECUCAO);
}
const trilha = (c) => (SEQ[c.funil] ? c.funil : 'OUT');
const msgIdDe = (c) => 'm_' + c.deal_id + '_' + (trilha(c) === 'OUT' ? '' : trilha(c) + '_') + c.proximo_passo;
return devidas($('Ler cadências ativas').all().map((i) => i.json), new Date().toISOString(), $('Executar').isExecuted, $('Ler mensagens enviadas').all().map((i) => i.json)).map((c) => ({ json: c }));

// ATOM2_W07 · Cadência condicional (Fluxo do Funil v1.0 §3; scripts de 09/10/2026).
// Três trilhas, em dias úteis (seg–sex, sem feriados nacionais), só em horário comercial (8h–18h, São Paulo):
//   OUT  (prospecção): D1 → D3 → D6 → D9 → D12; sem nome do decisor (D1 foi à recepção), D6 → D12 (o convite D9 não vai à recepção).
//   POS  (pós-diagnóstico, criada pelo W08 no "Pode enviar"): D9 (+2) → D12 (+3), sem marcar perdido.
//   PROP (pós-proposta, criada pelo W10): P2 "Acompanhamento da proposta" → P5 "Encerramento da proposta" (+3), sem marcar perdido.
// Cada passo é condicional: resposta, recusa, reunião ou opt-out encerram (o W08 muda o status da cadência).
// REGRA ABSOLUTA: nenhuma mensagem com preço antes da proposta (trava abaixo). Não alterna canal.
// SIMULACAO (padrão): grava a mensagem como "simulada", não avança a cadência nem mexe no Pipedrive —
// exceto registros de teste (company_id começa com "c_teste_"), que percorrem o fluxo inteiro sem enviar nada.
const API = 'https://api.pipedrive.com/v1';
const NOOP = { method: 'GET', url: API + '/users/me', body: {} };
const FERIADOS = ['2026-01-01', '2026-02-16', '2026-02-17', '2026-04-03', '2026-04-21', '2026-05-01', '2026-06-04', '2026-09-07', '2026-10-12', '2026-11-02', '2026-11-15', '2026-11-20', '2026-12-25',
  '2027-01-01', '2027-02-08', '2027-02-09', '2027-03-26', '2027-04-21', '2027-05-01', '2027-05-27', '2027-09-07', '2027-10-12', '2027-11-02', '2027-11-15', '2027-11-20', '2027-12-25'];
const SEQ = { OUT: { D1: ['D3', 2], D3: ['D6', 3], D6: ['D9', 3], D9: ['D12', 3], D12: [null, 0] }, POS: { D9: ['D12', 3], D12: [null, 0] }, PROP: { P2: ['P5', 3], P5: [null, 0] } };
// Até 10 mensagens por rodada de 15 min (espaça os envios e protege a reputação do número).
const LIMITE_POR_EXECUCAO = 10;
// Achados técnicos (faixa 3 do W04): não servem de gancho em mensagem ao dono da clínica.
const TECNICOS = ['H1_AUSENTE', 'SCHEMA_AUSENTE', 'SCHEMA_INVALIDO', 'CANONICAL_OUTRO_DOMINIO', 'SITEMAP_AUSENTE', 'SCHEMA_SEM_NEGOCIO', 'H1_MULTIPLOS', 'TITLE_LONGO', 'CANONICAL_AUSENTE', 'CONTEUDO_RASO', 'GEO_PRONTIDAO_BAIXA'];

// --- trava de preço e termos proibidos (bloco canônico de lib_guarda_preco.js) ---
// <guarda> — bloco canônico: copiado idêntico para W05, W05b, W07 e W08 por n8n/tools/sync_guarda.js (teste confere).
// Fronteiras Unicode: \b do JavaScript não trata "é", "à" etc. como letra.
const I = '(?<![\\p{L}\\p{N}])', F = '(?![\\p{L}\\p{N}])';
const rx = (corpo) => new RegExp(I + corpo + F, 'iu');
const EXTENSO = '(um|uma|dois|duas|tr[eê]s|quatro|cinco|seis|sete|oito|nove|dez|onze|doze|treze|quatorze|catorze|quinze|dezesseis|dezessete|dezoito|dezenove|vinte|trinta|quarenta|cinquenta|sessenta|setenta|oitenta|noventa|cem|cento|duzentos|duzentas|trezentos|trezentas|quatrocentos|quinhentos|seiscentos|setecentos|oitocentos|novecentos)';
const PRECO_RX = [
  /(R|US|U)?\s*[$＄]\s*\d/i,                                                                   // R$ 3.000, R $3000, US$ 500, $500
  rx('\\d{1,3}([.\\s]\\d{3})+([.,]\\d{2})?'),                                                 // 3.000 / 14.000,00 / 1 500,00
  rx('\\d+([.,]\\d+)?\\s*(mil|reais|k)'),                                                     // 3 mil, 900 reais, 3k
  rx(EXTENSO + '(\\s+e\\s+' + EXTENSO + ')*\\s+(mil|reais)'),                                 // três mil, dois mil e quinhentos
  rx('\\d+,\\d{2}'), rx('\\d+\\.\\d{2}'),                                                     // 500,00 / 500.00
  rx('\\d+([.,]\\d+)?\\s*(/\\s*m[eê]s|por m[eê]s|mensais|ao m[eê]s|/\\s*ano|por ano)'),       // 1500/mês, 990 mensais
  rx('\\d+\\s*x\\s*(de\\s*)?(R\\$\\s*)?\\d+'),                                                 // 12x 300, 2x de 750
  rx('(valor|custo|taxa|or[cç]amento|ticket|plano|investimento)\\s*(:|mensal|anual|de|é|e|fica|sai|total|inicial)?\\s*(R\\$\\s*)?\\d+'), // Valor: 1500, orçamento de 1500
  rx('(?<!(oportunidades|resultados|dados|casos|problemas|ganhos|melhorias|clientes|pacientes|n[uú]meros|exemplos|situa[cç][oõ]es|pessoas|avalia[cç][oõ]es|depoimentos|evid[eê]ncias|mudan[cç]as|benef[ií]cios)\\s)reais'),
  rx('pre[cç]os?'),
  rx('valor(es)?\\s+(de|do|da|para|é|e|fica|sai|total|mensal)'),
  rx('investimento\\s+(de|é|e|fica|sai|total|inicial|mensal)'),
  rx('(mensalidade|parcelas?|parcelado|entrada de|setup de|desconto|à vista|a vista|boleto|pix)'),
  rx('(custa|custo de|cobramos|sai por|fica por|a partir de)')
];
// Promessas e alegações proibidas (handoff §8; scripts de 09/10). "Ninguém pode garantir isso" (script ChatGPT) passa.
const PROIBIDOS = [/primeira posi[cç][aã]o/i, /topo do google/i, /garant(imos|ido|idos|ida|idas|o\b|ia de)/i, /posi[cç][aã]o\s*\d/i, /\b\d+\s*(visitas|clientes|pacientes) (por|ao) m[eê]s/i, /preju[ií]zo/i, /queda de vendas/i, /perdendo (clientes|pacientes|vendas)/i, /cliente oculto/i, /chatgpt (indicou|citou|recomendou)/i];
const bloqueios = (t) => [...PRECO_RX.filter((r) => r.test(String(t || ''))).map(() => 'preço antes da proposta'), ...PROIBIDOS.filter((r) => r.test(String(t || ''))).map((r) => 'termo proibido ' + r.source)];
// </guarda>

// --- tempo em São Paulo (UTC−3 fixo; o Brasil não tem horário de verão desde 2019) ---
const SP = (d) => new Date(new Date(d).getTime() - 3 * 3600 * 1000);
const diaSP = (d) => SP(d).toISOString().slice(0, 10);
const util = (dia) => { const w = new Date(dia + 'T12:00:00Z').getUTCDay(); return w !== 0 && w !== 6 && !FERIADOS.includes(dia); };
function horarioComercial(agora) { const s = SP(agora); const h = s.getUTCHours(); return util(s.toISOString().slice(0, 10)) && h >= 8 && h < 18; }
// Próximo envio: n dias úteis depois, às 9h de São Paulo (12h UTC).
function somarDiasUteis(agora, n) {
  let dia = diaSP(agora), c = 0;
  while (c < n) { const d = new Date(dia + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + 1); dia = d.toISOString().slice(0, 10); if (util(dia)) c++; }
  return dia + 'T12:00:00.000Z';
}

// --- scripts da biblioteca de 09/10/2026; sem nome do contato, o vocativo "[Nome], " sai ---
const SCRIPTS = {
  D3: '[Nome], posso te enviar o diagnóstico rápido que mencionei? É sobre [achado].',
  D6_CASE: '[Nome], já aplicamos melhorias semelhantes em [case autorizado].\nPosso mostrar o exemplo e o diagnóstico da [Empresa]?',
  D6: '[Nome], tenho uma sugestão prática para [achado]. Quer que eu envie?',
  D9: '[Nome], posso te mostrar a oportunidade em 15 minutos.\nFaz sentido conversarmos?',
  D12: '[Nome], vou encerrar por aqui para não incomodar.\nSe quiser avaliar as melhorias depois, fico à disposição.',
  P2: '[Nome], conseguiu avaliar a proposta?\nPosso esclarecer algum ponto?',
  P5: '[Nome], prefere manter em avaliação ou encerrar por enquanto?'
};
function preencher(modelo, nome, empresa, achado, caso) {
  let t = modelo.replace('[Empresa]', empresa).replace('[achado]', achado || 'as duas sugestões que preparei para o site').replace('[case autorizado]', caso || '');
  if (nome) return t.replace('[Nome]', nome);
  t = t.replace('[Nome], ', '');
  return t.charAt(0).toUpperCase() + t.slice(1);
}
// Case autorizado da mesma vertical (linhas "vertical: texto" em CASES_AUTORIZADOS; linha sem vertical vale para todas).
function caseDa(cfg, vertical) {
  for (const l of String(cfg.CASES_AUTORIZADOS || '').split('\n').map((x) => x.trim()).filter(Boolean)) {
    const m = l.match(/^(dental|medical|tires)\s*:\s*(.+)$/i);
    if (!m) return l;
    if (m[1].toLowerCase() === vertical) return m[2].trim();
  }
  return '';
}
// D3 usa o achado principal; D6 "sem case" usa o 2º achado comercial (outra conversa, não repete o D3). Achado técnico não vira gancho.
function mensagem(passo, ctx) {
  const { empresa: e, auditoria: a, principal: p, segundo: s2, cfg } = ctx;
  if (passo === 'D1') return a.mensagem_aprovada;
  const util = (f) => (f && f.trecho && !TECNICOS.includes(f.codigo) ? f.trecho : null);
  if (passo === 'D6') {
    const caso = caseDa(cfg || {}, e.vertical);
    return caso ? preencher(SCRIPTS.D6_CASE, e.contato_nome, e.nome, null, caso) : preencher(SCRIPTS.D6, e.contato_nome, e.nome, util(s2) || util(p), '');
  }
  return preencher(SCRIPTS[passo], e.contato_nome, e.nome, util(p), '');
}

const cfgMapa = (rows) => {
  const m = {};
  for (const r of rows || []) if (r && r.chave) m[r.chave] = String(r.valor ?? '');
  // MODO_EXECUCAO conservador: PRODUCAO só se todas as linhas disserem PRODUCAO.
  const modos = (rows || []).filter((r) => r && r.chave === 'MODO_EXECUCAO').map((r) => String(r.valor).trim().toUpperCase());
  m.MODO_EXECUCAO = modos.length && modos.every((x) => x === 'PRODUCAO') ? 'PRODUCAO' : 'SIMULACAO';
  return m;
};

// Cadências devidas agora, sem as que já têm a mensagem do passo registrada (em SIMULACAO a cadência não avança:
// sem esse filtro as mesmas 10 ocupariam todas as rodadas e as demais nunca seriam processadas).
// manual = execução manual: fora do horário comercial processa só registros de teste (c_teste_*).
function devidas(cadencias, agoraISO, manual, mensagens) {
  const agora = agoraISO || new Date().toISOString();
  const fora = !horarioComercial(agora);
  if (fora && !manual) return [];
  const ja = new Set((mensagens || []).filter((m) => m && m.msg_id).map((m) => m.msg_id));
  return (cadencias || []).filter((x) => x && (!fora || String(x.company_id).startsWith('c_teste_')) && x.status === 'ativa' && x.proximo_passo && String(x.proximo_em) <= agora && !ja.has(msgIdDe(x)))
    .sort((a, b) => String(a.proximo_em).localeCompare(String(b.proximo_em))).slice(0, LIMITE_POR_EXECUCAO);
}
const trilha = (c) => (SEQ[c.funil] ? c.funil : 'OUT');
const msgIdDe = (c) => 'm_' + c.deal_id + '_' + (trilha(c) === 'OUT' ? '' : trilha(c) + '_') + c.proximo_passo;
// Etapas do Pipedrive em que cada trilha pode seguir.
function etapasPermitidas(cfg, t) {
  const k = { OUT: ['OUT_PRONTO', 'OUT_CADENCIA'], POS: ['OUT_RESPONDEU', 'OUT_QUALIFICADO', 'IN_ATENDIMENTO', 'IN_QUALIFICADO'], PROP: ['OUT_PROPOSTA', 'OUT_NEGOCIACAO', 'IN_PROPOSTA', 'IN_NEGOCIACAO'] }[t];
  return k.map((x) => cfg['PD2_STAGE_' + x + '_ID']).filter(Boolean).map(String);
}

// Planeja os envios devidos: 1 item por cadência { msg?, cadencia, pd, evento, empresa? }.
// deals: { [deal_id]: { status, stage_id } | null } lido do Pipedrive na hora. null = negócio não existe (404) → encerra;
// ausente = falha passageira (429/5xx) → pula e tenta na próxima rodada.
function planejar(cadencias, empresas, auditorias, achados, cfgRows, agoraISO, deals, mensagens, manual) {
  const cfg = cfgMapa(cfgRows);
  const agora = agoraISO || new Date().toISOString();
  const E = Object.fromEntries((empresas || []).filter((e) => e && e.company_id).map((e) => [e.company_id, e]));
  const out = [];
  for (const c of devidas(cadencias, agora, manual, mensagens)) {
    const e = E[c.company_id];
    const t = trilha(c);
    const passo = c.proximo_passo;
    const teste = String(c.company_id).startsWith('c_teste_');
    const real = cfg.MODO_EXECUCAO === 'PRODUCAO' || teste;
    const ev = (tipo, motivo, dados) => ({ event_id: 'e_w07_' + c.deal_id + '_' + (t === 'OUT' ? '' : t + '_') + (passo || 'x') + '_' + tipo.toLowerCase(), correlation_id: 'deal_' + c.deal_id, company_id: c.company_id, workflow: 'ATOM2_W07', tipo, motivo, dados: JSON.stringify(dados || {}), ocorrido_em: agora });
    const encerrar = (motivo, tipo) => out.push({ cadencia: { deal_id: c.deal_id, status: 'encerrada', motivo_fim: motivo, atualizado_em: agora }, pd: { ...NOOP }, evento: ev(tipo, motivo) });
    if (!e) { encerrar('empresa não encontrada', 'CADENCIA_ERRO'); continue; }
    if (deals) {
      if (!(String(c.deal_id) in deals)) continue; // Pipedrive indisponível agora: tenta na próxima rodada
      const d = deals[String(c.deal_id)];
      if (!d || d.status !== 'open' || !etapasPermitidas(cfg, t).includes(String(d.stage_id))) { encerrar('negócio fora da cadência no Pipedrive (' + (d ? d.status + '/etapa ' + d.stage_id : 'não encontrado') + ')', 'CADENCIA_PIPEDRIVE'); continue; }
    }
    if (e.opt_out === true || String(e.opt_out) === 'true') { encerrar('opt-out', 'CADENCIA_OPTOUT'); continue; }
    if (!e.telefone) { encerrar('sem telefone', 'CADENCIA_SEM_CANAL'); continue; }
    // Auditoria aprovada mais recente (após um N1 refeito, vale o achado novo).
    const aud = (auditorias || []).filter((a) => a && a.company_id === e.company_id && a.qa_status === 'aprovado').sort((x, y) => String(y.qa_em || '').localeCompare(String(x.qa_em || '')))[0];
    if (!aud && t !== 'PROP') { encerrar('sem QA aprovado', 'CADENCIA_SEM_QA'); continue; }
    const doAud = (achados || []).filter((f) => f && aud && f.audit_id === aud.audit_id);
    const principal = aud ? (achados || []).find((f) => f && f.finding_id === aud.principal_finding_id) || null : null;
    const segundo = doAud.find((f) => f.usado_em === 'resumo' && f.finding_id !== (principal && principal.finding_id) && !TECNICOS.includes(f.codigo)) || null;
    const texto = mensagem(passo, { empresa: e, auditoria: aud || {}, principal, segundo, cfg });
    const msgId = msgIdDe(c);
    const base = { msg_id: msgId, company_id: e.company_id, deal_id: String(c.deal_id), direcao: 'saida', canal: 'whatsapp_n2', telefone: e.telefone, passo: (t === 'OUT' ? '' : t + '_') + passo, texto, modo: cfg.MODO_EXECUCAO + (teste ? '_TESTE' : ''), criado_em: agora };
    const b = t === 'PROP' ? bloqueios(texto || '').filter((x) => !x.startsWith('preço')) : bloqueios(texto || '');
    if (!texto) b.push('mensagem vazia (sem texto aprovado)');
    if (b.length) {
      out.push({ msg: { ...base, status: 'bloqueada', motivo: b.join('; ') }, cadencia: { deal_id: c.deal_id, status: 'pausada', motivo_fim: 'mensagem bloqueada: revisão humana', atualizado_em: agora }, pd: { ...NOOP }, evento: ev('MSG_BLOQUEADA', b.join('; ')) });
      continue;
    }
    // Envio real exige canal configurado; sem ele, PRODUCAO fica bloqueada (nada é enviado por fora).
    const canalOk = !!cfg.WA_N2_PHONE_NUMBER_ID;
    const status = !real ? 'simulada' : teste ? 'simulada_teste' : canalOk ? 'pronta_envio' : 'bloqueada';
    if (status === 'bloqueada') {
      out.push({ msg: { ...base, status, motivo: 'WhatsApp nº 2 não configurado (WA_N2_PHONE_NUMBER_ID)' }, cadencia: { deal_id: c.deal_id, atualizado_em: agora }, pd: { ...NOOP }, evento: ev('MSG_SEM_CANAL', 'WhatsApp não configurado') });
      continue;
    }
    if (!real) { out.push({ msg: { ...base, status, motivo: 'SIMULACAO: cadência não avança' }, cadencia: { deal_id: c.deal_id, atualizado_em: agora }, pd: { ...NOOP }, evento: ev('MSG_SIMULADA', base.passo) }); continue; }
    let [prox, dias] = (SEQ[t] || {})[passo] || [null, 0];
    if (t === 'OUT' && passo === 'D6' && !e.contato_nome) prox = 'D12'; // sem decisor identificado, o convite de 15 min não vai à recepção
    const f = (k) => cfg['PD2_FIELD_' + k];
    const body = {};
    if (t === 'OUT' && passo === 'D1' && cfg.PD2_STAGE_OUT_CADENCIA_ID) body.stage_id = Number(cfg.PD2_STAGE_OUT_CADENCIA_ID);
    if (t !== 'PROP' && f('TOQUE') && cfg['PD2_OPT_TOQUE_' + passo]) body[f('TOQUE')] = Number(cfg['PD2_OPT_TOQUE_' + passo]);
    if (f('ULTIMO_CONTATO')) body[f('ULTIMO_CONTATO')] = diaSP(agora);
    if (f('TEMPLATE')) body[f('TEMPLATE')] = (t === 'OUT' ? 'out_' : t.toLowerCase() + '_') + passo.toLowerCase() + '_v1';
    const fim = { OUT: 'Cadência encerrada sem resposta', POS: 'Pós-diagnóstico sem resposta: decidir (ligar ou encerrar)', PROP: 'Proposta sem resposta: decidir (ligar, manter ou encerrar)' }[t];
    if (f('PROXIMA_ACAO')) body[f('PROXIMA_ACAO')] = prox ? 'Cadência: ' + prox + ' em ' + somarDiasUteis(agora, dias).slice(0, 10) : fim;
    if (!prox && t === 'OUT') { body.status = 'lost'; body.lost_reason = 'Sem resposta'; if (f('TOQUE') && cfg.PD2_OPT_TOQUE_ENCERRADA) body[f('TOQUE')] = Number(cfg.PD2_OPT_TOQUE_ENCERRADA); }
    out.push({
      msg: { ...base, status, motivo: teste ? 'registro de teste: fluxo completo sem envio' : '' },
      cadencia: prox ? { deal_id: c.deal_id, passo_atual: passo, proximo_passo: prox, proximo_em: somarDiasUteis(agora, dias), ultimo_envio_em: agora, envios: Number(c.envios || 0) + 1, atualizado_em: agora }
        : { deal_id: c.deal_id, passo_atual: passo, proximo_passo: '', status: 'encerrada', motivo_fim: 'sem_resposta', ultimo_envio_em: agora, envios: Number(c.envios || 0) + 1, atualizado_em: agora },
      pd: { method: 'PUT', url: API + '/deals/' + c.deal_id, body },
      empresa: t === 'OUT' && passo === 'D1' ? { company_id: e.company_id, funil_etapa: 'F5', status_motivo: 'Contatado (cadência)', atualizado_em: agora } : !prox && t === 'OUT' ? { company_id: e.company_id, funil_etapa: 'F11', status_motivo: 'Perdido: sem resposta (D12)', atualizado_em: agora } : null,
      tarefa: !prox && t !== 'OUT' ? { deal_id: Number(c.deal_id), subject: fim, type: 'task', due_date: diaSP(agora) } : null,
      evento: ev(prox ? 'MSG_' + status.toUpperCase() : 'CADENCIA_FIM', base.passo)
    });
  }
  return out;
}

// Deals lidos do Pipedrive: sucesso → { status, stage_id }; 404 → null; outra falha → ausente (pula a cadência nesta rodada).
function mapaDeals(devidasLista, respostas) {
  const m = {};
  (devidasLista || []).forEach((c, i) => {
    const r = (respostas || [])[i] || {};
    if (r.success && r.data) m[String(c.deal_id)] = { status: r.data.status, stage_id: r.data.stage_id };
    else if (r.errorCode === 404 || /not found/i.test(String(r.error || ''))) m[String(c.deal_id)] = null;
  });
  return m;
}

const devs = $('Devidas agora').all().map((i) => i.json);
const deals = mapaDeals(devs, $('Ler negócio').all().map((i) => i.json));
return planejar(devs, $('Ler empresas').all().map((i) => i.json), $('Ler auditorias aprovadas').all().map((i) => i.json), $('Ler achados principais').all().map((i) => i.json), $('Ler configuração').all().map((i) => i.json), new Date().toISOString(), deals, $('Ler mensagens enviadas').all().map((i) => i.json), $('Executar').isExecuted).map((p) => ({ json: p }));

// ATOM2_W07 · Registros (trecho de n8n/code/w07_cadencia.js).
// Depois do nó HTTP: só avança a cadência se o Pipedrive aceitou o PUT; senão registra a falha e tenta de novo na próxima rodada.
function registros(planos, resps) {
  const out = [];
  planos.forEach((p, i) => {
    const r = resps[i] || {};
    const ok = !p.pd || p.pd.method !== 'PUT' || r.success === true;
    if (ok) {
      if (p.msg) out.push({ destino: 'mensagem', linha: p.msg });
      out.push({ destino: 'cadencia', linha: p.cadencia });
      if (p.empresa) out.push({ destino: 'empresa', linha: p.empresa });
      if (p.tarefa) out.push({ destino: 'tarefa', linha: p.tarefa });
      out.push({ destino: 'evento', linha: p.evento });
    } else {
      out.push({ destino: 'evento', linha: { ...p.evento, event_id: p.evento.event_id + '_crm_falha', tipo: 'CRM_FALHA', motivo: 'Pipedrive recusou a atualização do negócio; mensagem não registrada, tenta na próxima rodada', dados: JSON.stringify({ erro: r.error || r.error_info || null }) } });
    }
  });
  return out;
}

return registros($('Planejar').all().map((i) => i.json), $('Aplicar no Pipedrive').all().map((i) => i.json)).map((j) => ({ json: j }));
